import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

/**
 * Create a draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) {
    return customerResult;
  }

  const customer = customerResult.value;

  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  const enrichedLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const tierDiscount = TIER_DISCOUNTS[customer.tier] ?? 0;
    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : tierDiscount;
    if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return productResult;
    }

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  const invoice = {
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  };

  return ok(invoice);
}

/**
 * Calculate the total for a single line: qty times unitPrice.
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount for a single line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number}
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const discount = roundCents(lineTotal(line) * discountPercent / 100);
  return Math.max(0, discount);
}

/**
 * Calculate invoice totals.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const total = Math.max(0, subtotal - discount);
  return {
    subtotal,
    discount,
    total,
  };
}

/**
 * Add a line to an invoice, or increase qty if the SKU already exists.
 * @param {{ status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent?: number }> }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const discount = discountPercent ?? 0;
  if (typeof discount !== 'number' || discount < 0 || discount > 100) {
    return fail('DISCOUNT_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return productResult;
  }

  const product = productResult.value;
  const newLines = invoice.lines.map((line) => ({ ...line }));

  const existingLineIndex = newLines.findIndex((line) => line.sku === sku);
  if (existingLineIndex >= 0) {
    newLines[existingLineIndex].qty += qty;
  } else {
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: discount,
    });
  }

  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array<{ sku: string }> }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((line) => line.sku !== sku);
  const newInvoice = {
    ...invoice,
    lines: newLines,
  };

  return ok(newInvoice);
}

/**
 * Issue a draft invoice, assigning it a number and changing status to 'issued'.
 * @param {{ status: string, issueDate: string }} invoice
 * @param {string[]} existingNumbers - array of already-used invoice numbers
 * @returns {{ ok: true, value: any } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);
  const newInvoice = {
    ...invoice,
    number,
    status: 'issued',
  };

  return ok(newInvoice);
}

function isValidDate(dateString) {
  if (typeof dateString !== 'string') return false;
  const match = /^\d{4}-\d{2}-\d{2}$/.test(dateString);
  if (!match) return false;
  const date = new Date(dateString + 'T00:00:00Z');
  return date instanceof Date && !isNaN(date) && date.toISOString().startsWith(dateString);
}

