test('renderInvoiceText shows VAT line with 21% VAT', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert.match(text, /VAT: €/);
});

test('renderInvoiceText has VAT above total', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  const lines = text.split('\n');
  const vatLineIdx = lines.findIndex(l => l.startsWith('VAT: '));
  const totalLineIdx = lines.findIndex(l => l.startsWith('Total: '));
  assert(vatLineIdx >= 0, 'VAT line should exist');
  assert(totalLineIdx >= 0, 'Total line should exist');
  assert(vatLineIdx < totalLineIdx, 'VAT line should be before Total line');
});

test('renderInvoiceText with 0% VAT (no VAT line)', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'WORKSHOP-DAY', qty: 1 }],
  });

  assert.equal(invoiceResult.ok, true);
  const text = renderInvoiceText(invoiceResult.value);

  assert(!text.includes('VAT:'), 'VAT line should not appear for 0% VAT');
});

