test('invoiceTotals with gold tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 100 * 9500;
  const expectedDiscount = expectedSubtotal * 5 / 100;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount);
});

test('invoiceTotals with silver tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 100 * 9500;
  const expectedDiscount = expectedSubtotal * 2.5 / 100;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount);
});

test('invoiceTotals with standard tier (no discount)', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 100 * 9500;
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, expectedSubtotal);
});

test('invoiceTotals with explicit discount overriding tier', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 100, discountPercent: 0 },
    ],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 100 * 9500;
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, expectedSubtotal);
});

test('lineVat with 21% VAT rate', () => {
  const line = { qty: 100, unitPrice: 10000, discountPercent: 0, vatRate: 21 };
  const vat = lineVat(line);
  assert.equal(vat, 210000);
});

test('lineVat with 9% VAT rate', () => {
  const line = { qty: 100, unitPrice: 10000, discountPercent: 0, vatRate: 9 };
  const vat = lineVat(line);
  assert.equal(vat, 90000);
});

test('lineVat with 0% VAT rate', () => {
  const line = { qty: 100, unitPrice: 10000, discountPercent: 0, vatRate: 0 };
  const vat = lineVat(line);
  assert.equal(vat, 0);
});

