    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const silverResult = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  const standardResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(goldResult.ok, true);
  assert.equal(goldResult.value.lines[0].discountPercent, 5);

  assert.equal(silverResult.ok, true);
  assert.equal(silverResult.value.lines[0].discountPercent, 2.5);

  assert.equal(standardResult.ok, true);
  assert.equal(standardResult.value.lines[0].discountPercent, 0);
});

test('invoiceTotals with gold tier discount', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 100 }],
  });

  assert.equal(invoiceResult.ok, true);
  const totals = invoiceTotals(invoiceResult.value);
  const expectedSubtotal = 100 * 9500;
  const expectedDiscount = Math.round(expectedSubtotal * 5 / 100);
  const expectedVat = Math.round((expectedSubtotal - expectedDiscount) * 21 / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, expectedDiscount);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedSubtotal - expectedDiscount + expectedVat);
});

