  const totals = invoiceTotals(invoice);
  assert.equal(totals.subtotal, 0);
  assert.equal(totals.total, 0);
});

test('invoiceTotals includes VAT in total', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 2 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  assert.equal(result.ok, true);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.discount, 0);
  assert(totals.vat > 0, 'VAT should be greater than 0');
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

