test('invoiceTotals without discounts', () => {
  const invoice = {
    lines: [
      { qty: 5, unitPrice: 9500, discountPercent: 0, vatRate: 21 },
      { qty: 1, unitPrice: 120000, discountPercent: 0, vatRate: 21 },
    ],
  };
  const totals = invoiceTotals(invoice);
  const expectedSubtotal = 5 * 9500 + 1 * 120000;
  const expectedVat = Math.round(47500 * 21 / 100) + Math.round(120000 * 21 / 100);
  assert.equal(totals.subtotal, expectedSubtotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, expectedVat);
  assert.equal(totals.total, expectedSubtotal + expectedVat);
});

